class Solution { fun fractionToDecimal(numerator: Int, denominator: Int): String { if (numerator == 0) return "0"; val result = StringBuilder(); var n = numerator.toLong(); var d = denominator.toLong(); if ((n < 0) xor (d < 0)) result.append('-'); n = kotlin.math.abs(n); d = kotlin.math.abs(d); result.append(n / d); var remainder = n % d; if (remainder == 0L) return result.toString(); result.append('.'); val seen = mutableMapOf<Long, Int>(); while (remainder != 0L) { val index = seen[remainder]; if (index != null) { result.insert(index, '('); result.append(')'); break }; seen[remainder] = result.length; remainder *= 10; result.append(remainder / d); remainder %= d }; return result.toString() } }